14	export interface AdminStats {
15	  totalUsers: number;
16	  totalScans: number;
17	  activeUsers: number;
18	  failedScans: number;
19	  scanSuccessRate: number;
20	  newUsersToday: number;
21	  avgScoreThisMonth: number;
