28	async function fetchAdminStats(): Promise<AdminStats> {
29	  const supabase = createUntypedClient();
30	  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
31	  const todayMidnightUTC = new Date();
32	  todayMidnightUTC.setUTCHours(0, 0, 0, 0);
33	  const firstOfMonth = new Date();
34	  firstOfMonth.setDate(1);
35	  firstOfMonth.setHours(0, 0, 0, 0);
36	
37	  const [
38	    { count: totalUsers, error: usersError },
39	    { count: totalScans, error: scansError },
40	    { count: failedScans, error: failedError },
41	    { count: completedScans, error: completedError },
42	    { data: activeData, error: activeError },
43	    { count: newUsersToday, error: newUsersTodayError },
44	    { count: scansThisMonth, error: scansMonthError },
45	    { data: monthScores, error: monthScoresError },
46	  ] = await Promise.all([
47	    supabase.from("profiles").select("*", { count: "exact", head: true }),
48	    supabase.from("scans").select("*", { count: "exact", head: true }),
49	    supabase.from("scans").select("*", { count: "exact", head: true }).eq("status", "failed"),
50	    supabase.from("scans").select("*", { count: "exact", head: true }).eq("status", "completed"),
51	    supabase.from("scans").select("user_id").gte("created_at", sevenDaysAgo),
52	    supabase.from("profiles").select("*", { count: "exact", head: true }).gte("created_at", todayMidnightUTC.toISOString()),
53	    supabase.from("scans").select("*", { count: "exact", head: true }).gte("created_at", firstOfMonth.toISOString()),
54	    supabase.from("scans").select("overall_score").eq("status", "completed").gte("created_at", firstOfMonth.toISOString()).not("overall_score", "is", null),
55	  ]);
56	
57	  if (usersError) throw new Error(usersError.message);
58	  if (scansError) throw new Error(scansError.message);
59	  if (failedError) throw new Error(failedError.message);
60	  if (completedError) throw new Error(completedError.message);
61	  if (activeError) throw new Error(activeError.message);
62	  if (newUsersTodayError) throw new Error(newUsersTodayError.message);
63	  if (scansMonthError) throw new Error(scansMonthError.message);
64	  if (monthScoresError) throw new Error(monthScoresError.message);
65	
66	  const uniqueActiveUsers = new Set((activeData ?? []).map((r) => r.user_id)).size;
67	  const total = totalScans ?? 0;
68	  const completed = completedScans ?? 0;
69	  const scanSuccessRate = total > 0 ? Math.round((completed / total) * 1000) / 10 : 0;
70	  const scores = (monthScores ?? []).map((r) => r.overall_score as number).filter((s) => s !== null && s !== undefined);
71	  const avgScoreThisMonth = scores.length > 0 ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
72	
73	  return {
74	    totalUsers: totalUsers ?? 0, totalScans: total, activeUsers: uniqueActiveUsers,
75	    failedScans: failedScans ?? 0, scanSuccessRate, newUsersToday: newUsersToday ?? 0,
76	    avgScoreThisMonth, scansThisMonth: scansThisMonth ?? 0,
77	  };
78	}
