80	async function fetchUserGrowth(): Promise<UserGrowthDataPoint[]> {
81	  const supabase = createUntypedClient();
82	  const thirtyDaysAgo = subDays(new Date(), 30).toISOString();
83	
84	  const { data, error } = await supabase
85	    .from("profiles")
86	    .select("created_at")
87	    .gte("created_at", thirtyDaysAgo)
88	    .order("created_at", { ascending: true });
89	
90	  if (error) throw new Error(error.message);
91	
92	  const countsByDate: Record<string, number> = {};
93	  for (const row of data ?? []) {
94	    const day = format(new Date(row.created_at), "MMM d");
95	    countsByDate[day] = (countsByDate[day] ?? 0) + 1;
96	  }
97	
98	  const result: UserGrowthDataPoint[] = [];
99	  let cumulative = 0;
100	  for (let i = 29; i >= 0; i--) {
101	    const d = subDays(new Date(), i);
102	    const dateLabel = format(d, "MMM d");
103	    const count = countsByDate[dateLabel] ?? 0;
104	    cumulative += count;
105	    result.push({ date: dateLabel, count, cumulative });
106	  }
107	
108	  return result;
109	}
