111	async function fetchScanVolume(): Promise<ScanVolumeDataPoint[]> {
112	  const supabase = createUntypedClient();
113	  const sevenDaysAgo = subDays(startOfDay(new Date()), 6).toISOString();
114	
115	  const { data, error } = await supabase
116	    .from("scans")
117	    .select("created_at, status")
118	    .gte("created_at", sevenDaysAgo)
119	    .order("created_at", { ascending: true });
120	
121	  if (error) throw new Error(error.message);
122	
123	  const byDay: Record<string, { total: number; completed: number; failed: number }> = {};
124	
125	  for (const row of data ?? []) {
126	    const day = format(new Date(row.created_at), "EEE");
127	    if (!byDay[day]) byDay[day] = { total: 0, completed: 0, failed: 0 };
128	    byDay[day].total++;
129	    if (row.status === "completed") byDay[day].completed++;
130	    if (row.status === "failed") byDay[day].failed++;
131	  }
132	
133	  const result: ScanVolumeDataPoint[] = [];
134	  for (let i = 6; i >= 0; i--) {
135	    const day = format(subDays(new Date(), i), "EEE");
136	    const entry = byDay[day] ?? { total: 0, completed: 0, failed: 0 };
137	    result.push({ day, ...entry });
138	  }
139	
140	  return result;
141	}
