40	export function useChangePlan() {
41	  const supabase = createUntypedClient();
42	  const queryClient = useQueryClient();
43	  const { user } = useAuth();
44	
45	  return useMutation({
46	    mutationFn: async ({ userId, plan, previousPlan }: ChangePlanArgs) => {
47	      if (!user) throw new Error("Not authenticated");
48	
49	      const newLimit = plan === "agency" ? 500 : plan === "pro" ? 25 : 3;
50	
51	      const { error } = await supabase.from("profiles").update({ plan, scan_limit: newLimit }).eq("id", userId);
52	      if (error) throw new Error(error.message);
53	
54	      await writeAuditLog(user.id, "change_plan", "profile", userId, { previous_plan: previousPlan, new_plan: plan });
55	    },
56	    onSuccess: (_, { userId }) => {
57	      toast.success("Plan updated successfully");
58	      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
59	      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
60	      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
61	    },
62	    onError: (error: Error) => { toast.error(`Failed to update plan: ${error.message}`); },
63	  });
64	}
