37	async function fetchAdminUsers({
38	  page,
39	  pageSize,
40	  filter,
41	  sortColumn,
42	  sortAsc,
43	}: FetchAdminUsersParams): Promise<AdminUsersResult> {
44	  const supabase = createUntypedClient();
45	  let query = supabase
46	    .from("profiles")
47	    .select("*", { count: "exact" });
48	
49	  if (filter.search) {
50	    query = query.or(
51	      `email.ilike.%${filter.search}%,full_name.ilike.%${filter.search}%`
52	    );
53	  }
54	
55	  if (filter.plan) {
56	    query = query.eq("plan", filter.plan);
57	  }
58	
59	  if (filter.role) {
60	    query = query.eq("role", filter.role);
61	  }
62	
63	  const from = page * pageSize;
64	  const to = from + pageSize - 1;
65	
66	  query = query
67	    .order(sortColumn as string, { ascending: sortAsc })
68	    .range(from, to);
69	
70	  const { data, count, error } = await query;
71	
72	  if (error) throw new Error(error.message);
73	
74	  return {
75	    users: (data ?? []) as ProfileRow[],
76	    total: count ?? 0,
77	  };
78	}
